import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    w = tuple(map(int, data[1:1 + n]))
    level = {w: 0}
    while True:
        state = next(iter(level))
        if len(state) == 1:
            print(level[state])
            return
        nxt = {}
        for s, cost in level.items():
            for p in range(len(s) - 1):
                merged = s[:p] + (s[p] + s[p + 1],) + s[p + 2:]
                c = cost + abs(s[p] - s[p + 1])
                if merged not in nxt or c < nxt[merged]:
                    nxt[merged] = c
        level = nxt


main()
